// Generic, renderer-neutral, zero-copy mip payload. Offsets are relative to data.
export const PACK_SCHEMA='aether.material-pack/1';
export const MAPS=['color','normal','surface'];
const MAGIC=0x31504d41,MAX_BYTES=512*1024*1024;
export function encodeMaterialPack({recipe,levels,producer='cpu',generatorVersion='1',tileMeters=2,atlas={columns:4,rows:2,guardFraction:.125}}){
 let offset=0;const chunks=[],maps=MAPS.map(id=>({id,colorSpace:id==='color'?'srgb':'linear',channels:id==='surface'?'AO,roughness,metalness,height':id==='normal'?'tangent normal RGB':'base color RGB',mips:levels.map(l=>{const bytes=l[id];if(!(bytes instanceof Uint8Array)||bytes.length!==l.width*l.height*4)throw Error('Invalid mip bytes');const mip={width:l.width,height:l.height,offset,length:bytes.length};chunks.push(bytes);offset+=bytes.length;return mip;})}));
 const manifest={schema:PACK_SCHEMA,generatorVersion,producer,recipe,tileMeters,atlas,heightEncoding:{bias:.5,scalePerMeter:40},maps};const json=new TextEncoder().encode(JSON.stringify(manifest)),headerSize=Math.ceil((12+json.length)/4)*4,out=new Uint8Array(headerSize+offset),view=new DataView(out.buffer);view.setUint32(0,MAGIC,true);view.setUint32(4,json.length,true);view.setUint32(8,headerSize,true);out.set(json,12);let at=headerSize;for(const chunk of chunks){out.set(chunk,at);at+=chunk.length;}return out;
}
export function decodeMaterialPack(input){
 const bytes=input instanceof Uint8Array?input:new Uint8Array(input);if(bytes.byteLength<16||bytes.byteLength>MAX_BYTES)throw Error('Material pack size is invalid');const view=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);if(view.getUint32(0,true)!==MAGIC)throw Error('Unknown material pack');const length=view.getUint32(4,true),start=view.getUint32(8,true);if(length>1024*1024||start%4||start<12+length||start>bytes.length)throw Error('Invalid material pack header');const manifest=JSON.parse(new TextDecoder().decode(bytes.subarray(12,12+length)));if(manifest.schema!==PACK_SCHEMA||!Number.isFinite(manifest.tileMeters)||manifest.tileMeters<=0||!manifest.atlas||![manifest.atlas.columns,manifest.atlas.rows].every(n=>Number.isInteger(n)&&n>=1&&n<=16)||!Number.isFinite(manifest.atlas.guardFraction)||manifest.atlas.guardFraction<0||manifest.atlas.guardFraction>.25)throw Error('Unsupported material pack schema');
 if(!Array.isArray(manifest.maps)||manifest.maps.length!==3||new Set(manifest.maps.map(m=>m.id)).size!==3)throw Error('Invalid material map set');let occupied=[];const maps={};
 for(const map of manifest.maps){if(!MAPS.includes(map.id)||map.colorSpace!==(map.id==='color'?'srgb':'linear')||!Array.isArray(map.mips)||!map.mips.length||map.mips.length>10)throw Error('Invalid map descriptor');let previous;
  maps[map.id]=map.mips.map(m=>{if(![m.width,m.height,m.offset,m.length].every(Number.isSafeInteger)||m.width<1||m.height<1||m.width>4096||m.height>4096||m.offset<0||m.offset%4||m.length!==m.width*m.height*4||start+m.offset+m.length>bytes.length)throw Error('Invalid material mip range');if(previous&&(m.width!==Math.max(1,Math.floor(previous.width/2))||m.height!==Math.max(1,Math.floor(previous.height/2))))throw Error('Invalid mip pyramid');previous=m;occupied.push([m.offset,m.offset+m.length]);return{width:m.width,height:m.height,data:bytes.subarray(start+m.offset,start+m.offset+m.length)};});
 }
 const a=maps.color;for(const id of MAPS)if(maps[id].length!==a.length||maps[id].some((l,i)=>l.width!==a[i].width||l.height!==a[i].height))throw Error('Mismatched material pyramids');occupied.sort((a,b)=>a[0]-b[0]);if(occupied.some((r,i)=>i&&r[0]<occupied[i-1][1]))throw Error('Overlapping material map data');return{manifest,maps,bytes};
}
export async function sha256(bytes){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),n=>n.toString(16).padStart(2,'0')).join('');}
